-- fecha a conta dos caixas encerrados: calculado = abertura + vendas em dinheiro + suprimentos - sangrias - despesas em dinheiro
UPDATE caixa c SET c.valor_calculado = c.valor_abertura
  + COALESCE((SELECT SUM(v.valor_vend) FROM venda v WHERE v.id_caixa_fk=c.id_caixa AND v.forma_pagamento_vend='DINHEIRO' AND v.status_vend<>'CANCELADA'),0)
  + COALESCE((SELECT SUM(m.valor) FROM movimento_caixa m WHERE m.id_caixa_fk=c.id_caixa AND m.tipo='SUPRIMENTO'),0)
  - COALESCE((SELECT SUM(m.valor) FROM movimento_caixa m WHERE m.id_caixa_fk=c.id_caixa AND m.tipo='SANGRIA'),0)
  - COALESCE((SELECT SUM(d.valor) FROM despesa d WHERE d.id_caixa_fk=c.id_caixa AND d.forma_pagamento='DINHEIRO' AND d.pago=1),0)
WHERE c.id_caixa IN (@cx1,@cx2,@cx3,@cx4,@cx5);
UPDATE caixa SET valor_informado=valor_calculado+(0), diferenca=0.00 WHERE id_caixa=@cx1;
UPDATE caixa SET valor_informado=valor_calculado+(-5), diferenca=-5.00 WHERE id_caixa=@cx2;
UPDATE caixa SET valor_informado=valor_calculado+(2), diferenca=2.00 WHERE id_caixa=@cx3;
UPDATE caixa SET valor_informado=valor_calculado+(0), diferenca=0.00 WHERE id_caixa=@cx4;
UPDATE caixa SET valor_informado=valor_calculado+(0), diferenca=0.00 WHERE id_caixa=@cx5;

COMMIT;
